module top_tb;

    // Parameters
    parameter int N  = 120;
    parameter int M  = 256;
    parameter int P  = 1;
    parameter int DW = 8;
    parameter int N_in = N;
    parameter int M_in = M;
    parameter int es = 3;

    // Signals
    logic clk;
    logic rst;
    logic startLinearLayer;
    logic [DW-1:0] a [0:N_in-1][0:M_in-1];
    logic [DW-1:0] b [0:M_in-1][0:P-1];
    logic [DW-1:0] column_mult;
    logic done;
    logic [DW-1:0] matrix_out [0:N-1][0:P-1];

    // DUT instantiation
    top #(
        .N(N), .M(M), .P(P),
        .DW(DW), .N_in(N_in), .M_in(M_in), .es(es)
    ) dut (
        .clk(clk),
        .rst(rst),
        .startLinearLayer(startLinearLayer),
        .a(a),
        .b(b),
        .column_mult(column_mult),
        .done_new(done),
        .matrix_out(matrix_out)
    );

    // Clock generation
    always #5 clk = ~clk;
    integer file;
    // Test sequence
    initial begin
        // Initialize
        clk = 0;
        rst = 1;
        startLinearLayer = 0;
        file = $fopen("matrix_output.txt", "w");
         if (file == 0) begin
          $display("Error opening file!");
          $finish;
        end
        // Wait a few cycles
        repeat (2) @(negedge clk);
        rst = 0;
        @(negedge clk);
        for(int i = 0; i< 576; i++)
            for(int j = 0; j<25; j++)
                a[i][j] = '0;
        for(int i = 0; i < 25; i++)
            b[i][0] = '0;
        
